for name in ('app.py', 'vault.py', 'test_public.py', 'test_regression.py'):
    current = Path(name)
    print(f'\\n=== CURRENT {name} ===')
    for i, line in enumerate(current.read_text().splitlines(), 1):
        print(f'{i:4}: {line}')
    for root in ('.pre-repair', '.baseline'):
        old = Path(root) / name
        if old.exists():
            print(f'\\n=== DIFF {root}/{name} -> {name} ===')
            print(''.join(difflib.unified_diff(old.read_text().splitlines(keepends=True), current.read_text().splitlines(keepends=True), fromfile=str(old), tofile=str(current))))
        else:
            print(f'{root}/{name}: absent')
